"""Nexus IT Pack: Business Analyst Agent."""

from __future__ import annotations

from pydantic import BaseModel, Field

from nexus.providers.base import BaseModelProvider


class ProductProposal(BaseModel):
    """Structured proposal generated by the Business Analyst from vague requirements."""

    app_name: str = Field(description="URL-safe application name (lowercase slug)")
    title: str = Field(description="Human-readable product title")
    tagline: str = Field(description="One-sentence product value proposition")
    target_audience: str = Field(description="Primary user persona")
    user_stories: list[str] = Field(
        description="Key user stories: As a [user], I want to [action] so that [benefit]"
    )
    core_features: list[str] = Field(description="Numbered core features")
    ui_concept: str = Field(
        description="Description of the primary user dashboard/workflow"
    )
    wireframe_preview_html: str = Field(
        description="A clean HTML/Tailwind wireframe mockup representing the primary screen"
    )


class BusinessAnalystAgent:
    """
    Business Analyst Agent in the Nexus Core IT Pack.
    Translates vague, unrefined user prompts into clear technical proposals and wireframe concepts.
    """

    def __init__(self, provider: BaseModelProvider) -> None:
        self.provider = provider

    def analyze_requirements(self, raw_user_prompt: str) -> ProductProposal:
        """Transform raw idea into an actionable product proposal."""
        prompt = f"""You are an expert Lead Business Analyst & Product Strategist.
A non-technical user has the following idea:
\"{raw_user_prompt}\"

Transform this vague idea into a comprehensive, professional Product Proposal:
1. Define a concise, memorable app_name (slug).
2. Write crisp user stories.
3. Detail core features.
4. Design a clean UI concept.
5. Provide a realistic HTML/Tailwind wireframe preview that renders a mockup of the primary view.
"""
        system = (
            "You are a pragmatic, user-centric Business Analyst in an elite IT squad."
        )
        return self.provider.structured(
            prompt, ProductProposal, system_instruction=system
        )
